//! GFX10 (RDNA2) texture tiling, from AMD addrlib swizzle patterns (`tiling_tables.rs`,
//! generated by scripts/gen_tiling.py): 2D surfaces, 3D textures (thick blocks that tile x, y
//! and z together, or thin ones: 2D per depth slice) and linear surfaces.
//!
//! A pattern gives every address bit inside a block as the XOR of some x / y / z bits, so the
//! offset is linear over GF(2): `offset(x, y, z) = ox[x] ^ oy[y] ^ oz[z]`, small tables per
//! layout. Blocks (256 B / 4 KB / 64 KB) are laid out row-major; `Chain` lays out the mips.

use super::tiling_tables::{NIBBLE01, NIBBLE2, NIBBLE3, NIBBLE4, PATTERNS, PATTERNS_3D};

/// The part of GB_ADDR_CONFIG the XOR modes depend on (number of pipes and packers, log2).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PipeConfig {
    pub pipes_log2: u32,
    pub pkrs_log2: u32,
}

impl PipeConfig {
    /// row group in the RB+ tables (addrlib Gfx10Lib::HwlInitGlobalParams, m_colorBaseIndex)
    fn group(self) -> usize {
        (self.pipes_log2 + if self.pkrs_log2 >= 2 { 2 * self.pkrs_log2 - 2 } else { 0 }) as usize
    }
}

/// GFX10 SW_MODE values with an XOR (pipe / bank) component
fn is_xor(mode: u32) -> bool {
    mode >= 16
}

fn block_log2(mode: u32) -> Option<u32> {
    Some(match mode {
        1 | 2 => 8,
        5 | 6 | 21 | 22 => 12,
        9 | 10 | 17 | 18 | 24..=27 => 16,
        _ => return None,
    })
}

/// The address bits of one block of `mode` (`table`: the 2D or the 3D thick patterns).
fn pattern_bits(table: &[(u32, &[[u16; 4]])], mode: u32, elem_log2: u32, cfg: PipeConfig) -> Option<[u64; 20]> {
    let rows = table.iter().find(|p| p.0 == mode)?.1;
    let row = if is_xor(mode) { cfg.group() * 5 } else { 0 } + elem_log2 as usize;
    let idx = rows.get(row)?;
    let mut bits = [0u64; 20];
    bits[..8].copy_from_slice(&NIBBLE01[idx[0] as usize]);
    bits[8..12].copy_from_slice(&NIBBLE2[idx[1] as usize]);
    bits[12..16].copy_from_slice(&NIBBLE3[idx[2] as usize]);
    bits[16..20].copy_from_slice(&NIBBLE4[idx[3] as usize]);
    Some(bits)
}

/// How one tiled surface of `1 << elem_log2`-byte elements (pixels, or 4×4 blocks for BCn)
/// maps to memory.
#[derive(Clone, Debug)]
pub struct Layout {
    pub mode: u32,
    pub elem_log2: u32,
    /// block size in elements; `block_d` > 1: a 3D thick block (z-slices tiled together)
    pub block_w: usize,
    pub block_h: usize,
    pub block_d: usize,
    pub block_bytes: usize,
    /// XORed into every in-block byte offset: the pipe / bank swizzle a T# base address carries
    /// in its low bits (`base & (block_bytes - 1)`), 0 otherwise
    pub base_xor: usize,
    ox: Vec<u32>,
    oy: Vec<u32>,
    oz: Vec<u32>,
    /// the in-block bits the coordinates above the block give (XOR modes with many pipes take
    /// pipe bits from neighbouring blocks' coordinates), by `x >> log2(block_w)` etc.
    hx: Vec<u32>,
    hy: Vec<u32>,
    hz: Vec<u32>,
}

impl Layout {
    /// A 2D surface (or one slice of an array). `None` for unknown / reserved modes and
    /// elements over 16 B. Linear (0): rows padded to 256 bytes (addrlib
    /// Gfx10Lib::HwlComputeSurfaceInfoLinear), a "block" of 256 B, one row high.
    pub fn new(mode: u32, elem_log2: u32, cfg: PipeConfig) -> Option<Layout> {
        if elem_log2 > 4 {
            return None;
        }
        if mode == 0 {
            let bw = 256 >> elem_log2;
            let ox = (0..bw as u32).map(|x| x << elem_log2).collect();
            return Some(Layout { mode, elem_log2, block_w: bw, block_h: 1, block_d: 1, block_bytes: 256, base_xor: 0, ox, oy: vec![0], oz: vec![0], hx: vec![0], hy: vec![0], hz: vec![0] });
        }
        let blk = block_log2(mode)?;
        let bits = pattern_bits(PATTERNS, mode, elem_log2, cfg)?;
        // block size in elements: 256 B micro block, grown evenly in both directions
        let (w256, h256) = [(4, 4), (4, 3), (3, 3), (3, 2), (2, 2)][elem_log2 as usize];
        let amp = blk - 8;
        Some(Self::from_bits(mode, elem_log2, blk, &bits, (w256 + amp / 2, h256 + amp - amp / 2, 0)))
    }

    /// A 3D texture: the thick modes (4KB_S, 64KB_S / S_T, 4KB_S_X, 64KB_S_X, 64KB_D_X) tile
    /// x, y and z together in one block; linear and the thin ones (64KB_Z_X / R_X) lay out
    /// each depth slice as a 2D surface. `None`: a mode 3D textures cannot have (addrlib
    /// Gfx10Rsrc3dSwModeMask) or no pattern.
    pub fn new_3d(mode: u32, elem_log2: u32, cfg: PipeConfig) -> Option<Layout> {
        match mode {
            0 | 24 | 27 => Self::new(mode, elem_log2, cfg),
            5 | 9 | 17 | 21 | 25 | 26 if elem_log2 <= 4 => {
                let blk = block_log2(mode)?;
                let bits = pattern_bits(PATTERNS_3D, mode, elem_log2, cfg)?;
                // a 1 KB micro block (addrlib Block1K_3d), grown evenly in w, h, d
                // (Lib::ComputeThickBlockDimension)
                let (w1k, h1k, d1k) = [(4, 3, 3), (3, 3, 3), (3, 3, 2), (3, 2, 2), (2, 2, 2)][elem_log2 as usize];
                let (avg, rest) = ((blk - 10) / 3, (blk - 10) % 3);
                Some(Self::from_bits(mode, elem_log2, blk, &bits, (w1k + avg, h1k + avg + rest / 2, d1k + avg + u32::from(rest != 0))))
            }
            _ => None,
        }
    }

    /// The offset tables of a block `1 << wl` × `1 << hl` × `1 << dl` elements.
    fn from_bits(mode: u32, elem_log2: u32, blk: u32, bits: &[u64; 20], (wl, hl, dl): (u32, u32, u32)) -> Layout {
        // the in-block offset bits coordinate `c << lo` gives
        let table = |n: usize, shift: u32, lo: u32| -> Vec<u32> {
            (0..n as u32)
                .map(|c| {
                    let mut off = 0u32;
                    for (i, &b) in bits[..blk as usize].iter().enumerate() {
                        let mask = ((b >> shift) & 0xFFFF) as u32;
                        off |= ((mask & (c << lo)).count_ones() & 1) << i;
                    }
                    off
                })
                .collect()
        };
        let (bw, bh, bd) = (1usize << wl, 1usize << hl, 1usize << dl);
        // the pattern masks are 16 bits: coordinates above them do not matter
        let high = |l: u32, shift: u32| {
            let used = bits[..blk as usize].iter().fold(0u32, |m, &b| m | ((b >> shift) & 0xFFFF) as u32) >> l.min(16);
            table(1 << (32 - used.leading_zeros()), shift, l)
        };
        Layout {
            mode,
            elem_log2,
            block_w: bw,
            block_h: bh,
            block_d: bd,
            block_bytes: 1 << blk,
            base_xor: 0,
            ox: table(bw, 0, 0),
            oy: table(bh, 16, 0),
            oz: table(bd, 32, 0),
            hx: high(wl, 0),
            hy: high(hl, 16),
            hz: high(dl, 32),
        }
    }

    /// surface `w` × `h` elements: (blocks per row, blocks per column)
    pub fn blocks(&self, w: usize, h: usize) -> (usize, usize) {
        (w.div_ceil(self.block_w), h.div_ceil(self.block_h))
    }

    /// bytes the tiled surface occupies (padded to whole blocks)
    pub fn size(&self, w: usize, h: usize) -> usize {
        let (bx, by) = self.blocks(w, h);
        bx * by * self.block_bytes
    }

    /// byte offset of element (x, y) in a surface `w` elements wide
    pub fn offset(&self, x: usize, y: usize, w: usize) -> usize {
        self.offset_z(x, y, 0, w)
    }

    /// `offset` of element (x, y, z) of a thick block row (z < `block_d`; the caller places
    /// the z / `block_d` layers)
    pub fn offset_z(&self, x: usize, y: usize, z: usize, w: usize) -> usize {
        let pitch_blocks = w.div_ceil(self.block_w);
        let block = (y / self.block_h) * pitch_blocks + x / self.block_w;
        let hi = |t: &[u32], c: usize, b: usize| t[(c / b) % t.len()];
        let xor = self.ox[x % self.block_w] ^ self.oy[y % self.block_h] ^ self.oz[z % self.block_d] ^ hi(&self.hx, x, self.block_w) ^ hi(&self.hy, y, self.block_h) ^ hi(&self.hz, z, self.block_d);
        block * self.block_bytes + (xor as usize ^ self.base_xor)
    }

    /// tiled → linear rows (`w << elem_log2` bytes each); bytes past the end of `src` read as 0
    pub fn detile(&self, src: &[u8], w: usize, h: usize) -> Vec<u8> {
        let e = 1usize << self.elem_log2;
        let mut out = vec![0u8; w * h * e];
        for y in 0..h {
            for x in 0..w {
                let o = self.offset(x, y, w);
                if let Some(s) = src.get(o..o + e) {
                    let d = (y * w + x) * e;
                    out[d..d + e].copy_from_slice(s);
                }
            }
        }
        out
    }

    /// linear rows → tiled (the inverse of `detile`)
    pub fn tile(&self, linear: &[u8], w: usize, h: usize) -> Vec<u8> {
        let e = 1usize << self.elem_log2;
        let mut out = vec![0u8; self.size(w, h)];
        for y in 0..h {
            for x in 0..w {
                let o = self.offset(x, y, w);
                let s = (y * w + x) * e;
                out[o..o + e].copy_from_slice(&linear[s..s + e]);
            }
        }
        out
    }
}

/// Element of a GFX10 IMG_FORMAT: (log2 bytes, side in pixels: 1, or 4 for BCn blocks).
/// `None` for 96-bit formats (not tiled with these patterns) and unknown ones.
pub fn element(format: u32) -> Option<(u32, u32)> {
    Some(match format {
        1..=6 => (0, 1),
        7..=19 | 133..=136 => (1, 1),
        20..=61 | 130 | 132 => (2, 1),
        62..=71 => (3, 1),
        75..=77 => (4, 1),
        169 | 170 | 175 | 176 => (3, 4),
        171..=174 | 177..=182 => (4, 4),
        _ => return None,
    })
}

/// Layout of mip 0 of a T#'s image plus its size in elements. The swizzle the base address
/// carries below the block size becomes `base_xor`; the data starts at
/// `address & !(block_bytes - 1)`.
pub fn image_layout(t: &super::desc::Image, cfg: PipeConfig) -> Option<(Layout, usize, usize)> {
    let (e, side) = element(t.format)?;
    let mut l = Layout::new(t.swizzle_mode, e, cfg)?;
    l.base_xor = (t.address as usize) & (l.block_bytes - 1);
    Some((l, t.width.div_ceil(side) as usize, t.height.div_ceil(side) as usize))
}

/// One mip level of a tiled surface, in elements.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct MipLevel {
    pub width: usize,
    pub height: usize,
    /// depth slices (3D), else 1
    pub depth: usize,
    /// byte offset of the level's first block from the start of its slice
    pub offset: usize,
    /// width in elements the level's blocks are laid out for (the tail block's width in the tail)
    pub pitch: usize,
    /// where the level lies inside the mip tail block (levels in the tail), else (0, 0)
    pub origin: (usize, usize),
    /// a level in the mip tail: its byte offset inside the tail block
    pub tail: Option<usize>,
}

/// The mip chain of a tiled surface (addrlib Gfx10Lib::ComputeSurfaceInfoMacroTiled /
/// MicroTiled / HwlComputeSurfaceInfoLinear). Per slice: first the mip tail – one block shared
/// by the smallest levels (64 KB / 4 KB blocks only) – then the other levels from the smallest
/// to mip 0; slices follow each other `slice_bytes` apart. A slice is one array slice, one
/// depth slice of a thin 3D texture, or one layer of `layout.block_d` depth slices of a thick
/// one (every level's z-slices of that layer). On the retail TTPF archive the space between
/// textures is exactly this size for 909 of its 912 textures.
#[derive(Clone, Debug)]
pub struct Chain {
    pub layout: Layout,
    pub levels: Vec<MipLevel>,
    pub slice_bytes: usize,
}

impl Chain {
    /// `width` × `height` pixels, `side` pixels per element side (4 for BCn), `mips` levels;
    /// a level is the pixel size halved, rounded up to whole elements (as D3D12 sizes it).
    pub fn new(layout: Layout, width: u32, height: u32, side: u32, mips: u32) -> Chain {
        Self::new_3d(layout, width, height, 1, side, mips)
    }

    /// `new` for a 3D texture `depth` slices deep (levels halve the depth too); a thin layout
    /// (`block_d` 1) is 2D per depth slice.
    pub fn new_3d(layout: Layout, width: u32, height: u32, depth: u32, side: u32, mips: u32) -> Chain {
        let mips = mips.max(1) as usize;
        let (bw, bh) = (layout.block_w, layout.block_h);
        let thick = layout.block_d > 1;
        let blk = layout.block_bytes.trailing_zeros() as usize;
        let size = |i: usize| (((width >> i).max(1)).div_ceil(side) as usize, ((height >> i).max(1)).div_ceil(side) as usize);
        // what a level is padded from: mip 0's elements halved rounding up (addrlib ShiftCeil;
        // the console's layout library agrees), which only differs for odd sizes
        let (w0, h0) = (width.div_ceil(side) as usize, height.div_ceil(side) as usize);
        let padded = |i: usize| (w0.div_ceil(1 << i), h0.div_ceil(1 << i));
        let depth_of = |i: usize| (depth >> i).max(1) as usize;
        // the largest level the tail holds (GetMipTailDim: a thick block halves h, w or d by
        // log2(block) % 3) and at most this many levels in it (GetMaxNumMipsInTail)
        let (tw, th) = if !thick {
            // Z (depth) modes of 1- and 2-byte elements: 64 × 128 elements, as for 4-byte ones
            // (seen on the console's layout library)
            if layout.mode != 0 && layout.mode.is_multiple_of(4) && layout.elem_log2 <= 1 {
                (bw / 4, bh >> (1 - layout.elem_log2))
            } else {
                (bw / 2, bh)
            }
        } else {
            match blk % 3 {
                0 => (bw, bh / 2),
                1 => (bw / 2, bh),
                _ => (bw, bh),
            }
        };
        let eff = if thick { blk - (blk - 8) / 3 } else { blk };
        let max_tail = match eff {
            0..=8 => 0, // 256 B blocks: no tail
            9..=11 => 1 + (1 << (eff - 9)),
            _ => eff - 4,
        };
        let first_tail = if mips > 1 && max_tail > 0 {
            (0..mips)
                .find(|&i| {
                    let (w, h) = padded(i);
                    w <= tw && h <= th && mips - i <= max_tail
                })
                .unwrap_or(mips)
        } else {
            mips
        };
        let mut levels = vec![MipLevel::default(); mips];
        let mut offset = if first_tail < mips { layout.block_bytes } else { 0 };
        for i in (0..first_tail).rev() {
            let (w, h) = size(i);
            let (pw, ph) = padded(i);
            levels[i] = MipLevel { width: w, height: h, depth: depth_of(i), offset, pitch: pw.div_ceil(bw) * bw, origin: (0, 0), tail: None };
            offset += layout.size(pw, ph);
        }
        // a level in the tail: its offset there (256-byte units, largest level first) gives its
        // origin, x from the odd and y from the even address bits above 256 B, in 256 B
        // micro blocks (Block256_2d, or Block256_3d for a thick layout)
        let e = layout.elem_log2 as usize;
        let (w256, h256) = if thick { (1usize << [3, 2, 2, 2, 1][e], 1usize << [2, 2, 2, 1, 1][e]) } else { (1usize << [4, 4, 3, 3, 2][e], 1usize << [4, 3, 3, 2, 2][e]) };
        for i in first_tail..mips {
            let m = max_tail - 1 - (i - first_tail);
            let at = if m > 6 { 16usize << m } else { m << 8 };
            let (mut mx, mut my) = (0, 0);
            for b in 0..6 {
                mx |= ((at >> (9 + 2 * b)) & 1) << b;
                my |= ((at >> (8 + 2 * b)) & 1) << b;
            }
            let (w, h) = size(i);
            levels[i] = MipLevel { width: w, height: h, depth: depth_of(i), offset: 0, pitch: bw, origin: (mx * w256, my * h256), tail: Some(at) };
        }
        Chain { layout, levels, slice_bytes: offset }
    }

    /// Slices a 3D texture takes (depth slices, or thick layers of `block_d` of them).
    pub fn layers(&self) -> usize {
        self.levels[0].depth.div_ceil(self.layout.block_d)
    }

    /// element (x, y) of level `l` in array slice `slice` (from the slice's start): the slice
    /// is z of the 2D patterns – the XOR modes take pipe bits from it
    fn element_at(&self, l: &MipLevel, x: usize, y: usize, slice: usize) -> usize {
        l.offset + self.layout.offset_z(x + l.origin.0, y + l.origin.1, slice, l.pitch)
    }

    /// element (x, y, z) of level `l` from the start of the texture (all its slices)
    pub fn element_at_z(&self, l: &MipLevel, x: usize, y: usize, z: usize) -> usize {
        let bd = self.layout.block_d;
        (z / bd) * self.slice_bytes + l.offset + self.layout.offset_z(x + l.origin.0, y + l.origin.1, z, l.pitch)
    }

    /// level `i` of a 3D texture (`mem` = all its slices) → its depth slices of linear rows;
    /// bytes past the end of `mem` read as 0
    pub fn detile_volume(&self, mem: &[u8], i: usize) -> Vec<u8> {
        let l = self.levels[i];
        let e = 1usize << self.layout.elem_log2;
        let mut out = vec![0u8; l.width * l.height * l.depth * e];
        for z in 0..l.depth {
            for y in 0..l.height {
                for x in 0..l.width {
                    let o = self.element_at_z(&l, x, y, z);
                    if let Some(s) = mem.get(o..o + e) {
                        out[((z * l.height + y) * l.width + x) * e..][..e].copy_from_slice(s);
                    }
                }
            }
        }
        out
    }

    /// depth slices of linear rows of level `i` → their places in a 3D texture (`dst`)
    pub fn tile_volume(&self, dst: &mut [u8], i: usize, linear: &[u8]) {
        let l = self.levels[i];
        let e = 1usize << self.layout.elem_log2;
        for z in 0..l.depth {
            for y in 0..l.height {
                for x in 0..l.width {
                    let o = self.element_at_z(&l, x, y, z);
                    dst[o..o + e].copy_from_slice(&linear[((z * l.height + y) * l.width + x) * e..][..e]);
                }
            }
        }
    }

    /// level `i` of array slice `slice` (`src` = the slice's bytes) → linear rows of elements;
    /// bytes past the end of `src` read as 0
    pub fn detile_level(&self, src: &[u8], i: usize, slice: usize) -> Vec<u8> {
        let l = self.levels[i];
        let t = &self.layout;
        let e = 1usize << t.elem_log2;
        let mut out = vec![0u8; l.width * l.height * e];
        if t.mode == 0 && t.base_xor == 0 && l.origin == (0, 0) {
            // linear: a row's elements are contiguous, so it is copied whole (the elements that
            // are all in `src`, as below) – a video plane of 3840×2160 is 2160 copies, not 8 M
            let row = l.width * e;
            for y in 0..l.height {
                let o = self.element_at(&l, 0, y, slice);
                let n = src.len().saturating_sub(o).min(row) / e * e;
                if n > 0 {
                    out[y * row..][..n].copy_from_slice(&src[o..o + n]);
                }
            }
            return out;
        }
        // `element_at` (`Layout::offset_z`) split: what depends on x alone once per level, what
        // depends on y (and the slice) once per row – per element only two lookups and an XOR.
        // Element by element it was most of a retail game's render thread while it streamed
        // textures the CPU writes.
        let hi = |tab: &[u32], c: usize, b: usize| tab[(c / b) % tab.len()];
        let pitch_blocks = l.pitch.div_ceil(t.block_w);
        let columns: Vec<(usize, u32)> = (0..l.width)
            .map(|x| {
                let x = x + l.origin.0;
                (x / t.block_w, t.ox[x % t.block_w] ^ hi(&t.hx, x, t.block_w))
            })
            .collect();
        let z = t.oz[slice % t.block_d] ^ hi(&t.hz, slice, t.block_d);
        for (y, row) in out.chunks_exact_mut(l.width * e).enumerate() {
            let y = y + l.origin.1;
            let row_blocks = (y / t.block_h) * pitch_blocks;
            let yz = t.oy[y % t.block_h] ^ hi(&t.hy, y, t.block_h) ^ z;
            for (&(block_x, x), dst) in columns.iter().zip(row.chunks_exact_mut(e)) {
                let o = l.offset + (row_blocks + block_x) * t.block_bytes + ((x ^ yz) as usize ^ t.base_xor);
                if let Some(s) = src.get(o..o + e) {
                    dst.copy_from_slice(s);
                }
            }
        }
        out
    }

    /// Independent element-by-element oracle retained for the differential regression.
    #[cfg(test)]
    fn detile_level_slow(&self, src: &[u8], i: usize, slice: usize) -> Vec<u8> {
        let l = self.levels[i];
        let e = 1usize << self.layout.elem_log2;
        let mut out = vec![0u8; l.width * l.height * e];
        for y in 0..l.height {
            for x in 0..l.width {
                let o = self.element_at(&l, x, y, slice);
                if let Some(s) = src.get(o..o + e) {
                    out[(y * l.width + x) * e..][..e].copy_from_slice(s);
                }
            }
        }
        out
    }

    /// linear rows of level `i` → its place in array slice `slice` (`dst`, `slice_bytes` long)
    pub fn tile_level(&self, dst: &mut [u8], i: usize, slice: usize, linear: &[u8]) {
        let l = self.levels[i];
        let e = 1usize << self.layout.elem_log2;
        for y in 0..l.height {
            for x in 0..l.width {
                let o = self.element_at(&l, x, y, slice);
                dst[o..o + e].copy_from_slice(&linear[(y * l.width + x) * e..][..e]);
            }
        }
    }
}

/// The mip chain of a T#'s image (all `max_mip + 1` levels of the resource, base swizzle in
/// `base_xor`); the data starts at `address & !(block_bytes - 1)`.
pub fn image_chain(t: &super::desc::Image, cfg: PipeConfig) -> Option<Chain> {
    let (e, side) = element(t.format)?;
    let d3 = matches!(t.ty, super::desc::ImageType::D3);
    let mut l = if d3 { Layout::new_3d(t.swizzle_mode, e, cfg)? } else { Layout::new(t.swizzle_mode, e, cfg)? };
    l.base_xor = (t.address as usize) & (l.block_bytes - 1);
    let depth = if d3 { t.depth.max(1) } else { 1 };
    Some(Chain::new_3d(l, t.width, t.height, depth, side, t.max_mip + 1))
}

#[cfg(test)]
mod tests {
    use super::*;

    const MODES: [u32; 14] = [1, 2, 5, 6, 9, 10, 17, 18, 21, 22, 24, 25, 26, 27];

    fn configs() -> Vec<PipeConfig> {
        let mut v = vec![];
        for (p, k) in [(0, 0), (1, 0), (2, 0), (3, 1), (2, 2), (3, 2), (4, 2), (3, 3), (4, 3), (5, 3)] {
            v.push(PipeConfig { pipes_log2: p, pkrs_log2: k });
        }
        v
    }

    /// Linear levels are copied a row at a time: the same bytes as element by element, for every
    /// element size, padded rows, every mip and a source cut short (inside a row and inside an
    /// element).
    #[test]
    fn linear_levels_detile_by_rows_as_by_elements() {
        let by_elements = |c: &Chain, src: &[u8], i: usize| {
            let l = c.levels[i];
            let e = 1usize << c.layout.elem_log2;
            let mut out = vec![0u8; l.width * l.height * e];
            for y in 0..l.height {
                for x in 0..l.width {
                    let o = c.element_at(&l, x, y, 0);
                    if let Some(s) = src.get(o..o + e) {
                        out[(y * l.width + x) * e..][..e].copy_from_slice(s);
                    }
                }
            }
            out
        };
        for e in 0..5u32 {
            for (w, h, mips) in [(3840u32, 4u32, 1u32), (1920, 3, 1), (77, 13, 4), (1, 1, 1), (300, 200, 9)] {
                let c = Chain::new(Layout::new(0, e, PipeConfig { pipes_log2: 0, pkrs_log2: 0 }).unwrap(), w, h, 1, mips);
                let full: Vec<u8> = (0..c.slice_bytes).map(|k| (k * 7 + 3) as u8 | 1).collect();
                for cut in [full.len(), full.len() / 2 + 1, 5, 0] {
                    let src = &full[..cut];
                    for i in 0..c.levels.len() {
                        assert_eq!(c.detile_level(src, i, 0), by_elements(&c, src, i), "e{e} {w}x{h} level {i} src {cut} B");
                    }
                }
            }
        }
    }


    /// `detile_level` (offsets split by row and column) gives the bytes element-by-element
    /// `element_at` does: every mode, element size and pipe configuration, every level (mip
    /// tails too), a base swizzle and a slice, and a source cut short (bytes past it read as 0).
    #[test]
    fn detile_level_matches_element_by_element() {
        for mode in MODES {
            for e in 0..5u32 {
                for cfg in configs() {
                    let mut lay = Layout::new(mode, e, cfg).unwrap();
                    lay.base_xor = (lay.block_bytes / 2) & !((1 << e) - 1);
                    let c = Chain::new(lay, 77, 45, 1, 7);
                    let mem: Vec<u8> = (0..c.slice_bytes * 2).map(|i| (i * 131 % 251) as u8).collect();
                    let short = &mem[..mem.len() * 3 / 5];
                    let es = 1usize << e;
                    for (k, l) in c.levels.iter().enumerate() {
                        for (slice, src) in [(0, &mem[..]), (3, short)] {
                            let mut want = vec![0u8; l.width * l.height * es];
                            for y in 0..l.height {
                                for x in 0..l.width {
                                    let o = c.element_at(l, x, y, slice);
                                    if let Some(s) = src.get(o..o + es) {
                                        want[(y * l.width + x) * es..][..es].copy_from_slice(s);
                                    }
                                }
                            }
                            assert!(c.detile_level(src, k, slice) == want, "mode {mode} e {e} {cfg:?} level {k} slice {slice}");
                        }
                    }
                }
            }
        }
    }

    /// every mode, element size and pipe configuration: the in-block mapping is a permutation
    /// of the block's elements (catches a mis-parsed table or a wrong block shape)
    #[test]
    fn every_pattern_is_a_permutation_of_its_block() {
        for mode in MODES {
            for e in 0..5 {
                for cfg in configs() {
                    let l = Layout::new(mode, e, cfg).unwrap();
                    assert_eq!(l.block_w * l.block_h << e, l.block_bytes, "mode {mode} e {e}");
                    let mut seen = vec![false; l.block_bytes >> e];
                    for y in 0..l.block_h {
                        for x in 0..l.block_w {
                            let o = l.offset(x, y, l.block_w);
                            assert_eq!(o & ((1 << e) - 1), 0, "mode {mode} e {e} {cfg:?}: misaligned");
                            assert!(!std::mem::replace(&mut seen[o >> e], true), "mode {mode} e {e} {cfg:?}: ({x},{y}) collides");
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn high_coordinate_tables_keep_their_offsets_at_one_period() {
        let full = |bits: &[u64; 20], blk: u32, l: u32, shift: u32| -> Vec<u32> {
            (0..1u32 << (16 - l.min(16)))
                .map(|c| {
                    let mut off = 0u32;
                    for (i, &b) in bits[..blk as usize].iter().enumerate() {
                        let mask = ((b >> shift) & 0xFFFF) as u32;
                        off |= ((mask & (c << l)).count_ones() & 1) << i;
                    }
                    off
                })
                .collect()
        };
        let check = |l: &Layout, bits: &[u64; 20], what: &str| {
            let blk = l.block_bytes.trailing_zeros();
            for (t, b, shift) in [(&l.hx, l.block_w, 0), (&l.hy, l.block_h, 16), (&l.hz, l.block_d, 32)] {
                let want = full(bits, blk, b.trailing_zeros(), shift);
                assert!(t.len().is_power_of_two() && t.len() <= want.len(), "{what}: table of {} for {}", t.len(), want.len());
                for c in (0..1usize << 18).step_by(3).chain([u32::MAX as usize, (1 << 40) + 5]) {
                    assert_eq!(t[c % t.len()], want[c % want.len()], "{what}: shift {shift} coordinate block {c}");
                }
            }
            assert!(l.hz.len() <= 64, "{what}: {} z entries", l.hz.len());
        };
        for cfg in configs() {
            for e in 0..5 {
                for mode in MODES {
                    let l = Layout::new(mode, e, cfg).unwrap();
                    check(&l, &pattern_bits(PATTERNS, mode, e, cfg).unwrap(), &format!("2D mode {mode} e {e} {cfg:?}"));
                }
                for mode in [5u32, 9, 17, 21, 25, 26] {
                    let l = Layout::new_3d(mode, e, cfg).unwrap();
                    check(&l, &pattern_bits(PATTERNS_3D, mode, e, cfg).unwrap(), &format!("3D mode {mode} e {e} {cfg:?}"));
                }
            }
        }
    }

    /// Sizes of retail textures (TTPF): the space each takes in the archive.
    #[test]
    fn mip_chain_sizes_match_retail_textures() {
        let cfg = PipeConfig { pipes_log2: 0, pkrs_log2: 0 };
        // (mode, element log2, side, width, height, mips, bytes)
        for (mode, e, side, w, h, mips, bytes) in [
            (5, 4, 4, 128, 1024, 5, 192512), // BC7, 4 KB tiles
            (5, 2, 1, 128, 128, 7, 90112),   // BGRA8
            (5, 4, 4, 512, 64, 9, 65536),
            (5, 3, 4, 64, 512, 9, 61440), // BC1
            (10, 4, 4, 2048, 2048, 1, 4194304),
            (10, 4, 4, 512, 512, 8, 393216), // one slice of a 32-slice array
            (5, 4, 4, 16, 16, 5, 4096),      // all in the tail
        ] {
            let c = Chain::new(Layout::new(mode, e, cfg).unwrap(), w, h, side, mips);
            assert_eq!(c.slice_bytes, bytes, "{w}x{h} e{e} mode {mode} mips {mips}");
        }
    }

    /// The fast `detile_level` (row and column offsets split) gives what the element-by-element one
    /// gives: every mode, element size and pipe configuration, levels in and out of the tail,
    /// array slices, a base swizzle, and a source cut short.
    /// Original differential test by gw1337x (PR #283 comment 7116115692), extended
    /// with zero/noncanonical XORs and cuts inside individual elements and rows.
    #[test]
    fn fast_detile_matches_element_by_element() {
        let mut modes = vec![0u32];
        modes.extend(MODES);
        for mode in modes {
            for e in 0..5u32 {
                for cfg in configs() {
                    let Some(lay) = Layout::new(mode, e, cfg) else { continue };
                    let aligned = (0x5a5 << e) & (lay.block_bytes - 1) & !((1 << e) - 1);
                    let mut xors = vec![0, aligned, aligned | 1, lay.block_bytes + (1 << e)];
                    xors.sort_unstable();
                    xors.dedup();
                    for base_xor in xors {
                        let mut layout = lay.clone();
                        layout.base_xor = base_xor;
                        let c = Chain::new(layout, 70, 37, 1, 4);
                        let mut src = vec![0u8; c.slice_bytes * 2];
                        for (k, b) in src.iter_mut().enumerate() {
                            *b = (k as u32).wrapping_mul(2654435761).rotate_right(13) as u8;
                        }
                        let mut cuts = vec![0, 1, (1 << e) - 1, 1 << e, (1 << e) + 1, c.slice_bytes / 3, c.slice_bytes - 1, src.len() - 1];
                        cuts.sort_unstable();
                        cuts.dedup();
                        for i in 0..c.levels.len() {
                            for slice in 0..2 {
                                assert_eq!(c.detile_level(&src, i, slice), c.detile_level_slow(&src, i, slice), "mode {mode} e {e} {cfg:?} xor {base_xor:#x} level {i} slice {slice}");
                            }
                            for &cut in &cuts {
                                let short = &src[..cut];
                                assert_eq!(c.detile_level(short, i, 0), c.detile_level_slow(short, i, 0), "mode {mode} e {e} {cfg:?} xor {base_xor:#x} level {i}, cut {cut}");
                            }
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn linear_detile_truncated_element_is_entirely_zero() {
        let cfg = PipeConfig { pipes_log2: 0, pkrs_log2: 0 };
        for log2 in 1..=4 {
            let e = 1usize << log2;
            let c = Chain::new(Layout::new(0, log2, cfg).unwrap(), 3, 2, 1, 1);
            let partial = c.element_at(&c.levels[0], 1, 1, 0) + e - 1;
            let src = vec![0xA5; partial];
            let mut expected = vec![0xA5; 4 * e]; // first row and the first element of row two
            expected.resize(6 * e, 0);
            assert_eq!(c.detile_level(&src, 0, 0), expected, "log2 {log2}: partial elements must not leak prefix bytes");
        }
    }

    /// Every level of a chain (with a mip tail) gets its own elements: tiling all levels with
    /// distinct values and detiling them gives each back unchanged.
    #[test]
    fn mip_chain_levels_do_not_overlap() {
        for (mode, e, w, h, mips) in [(5u32, 2u32, 128u32, 96u32, 8u32), (10, 4, 64, 64, 7), (10, 0, 512, 128, 10), (1, 2, 40, 24, 6)] {
            let c = Chain::new(Layout::new(mode, e, PipeConfig { pipes_log2: 0, pkrs_log2: 0 }).unwrap(), w, h, 1, mips);
            let mut slice = vec![0u8; c.slice_bytes];
            let mut want = Vec::new();
            let mut n = 0u32;
            for (i, l) in c.levels.iter().enumerate() {
                let lin: Vec<u8> = (0..l.width * l.height << e)
                    .map(|_| {
                        n = n.wrapping_mul(1_103_515_245).wrapping_add(12345);
                        (n >> 16) as u8 | 1
                    })
                    .collect();
                c.tile_level(&mut slice, i, 0, &lin);
                want.push(lin);
            }
            for (i, lin) in want.iter().enumerate() {
                assert_eq!(&c.detile_level(&slice, i, 0), lin, "mode {mode} e{e}: level {i} overwritten");
            }
        }
    }

    /// The 3D thick modes: every element size and pipe configuration maps a w × h × d block
    /// onto its bytes one to one.
    #[test]
    fn every_thick_pattern_is_a_permutation_of_its_block() {
        for mode in [5u32, 9, 17, 21, 25, 26] {
            for e in 0..5 {
                for cfg in configs() {
                    let l = Layout::new_3d(mode, e, cfg).unwrap();
                    assert!(l.block_d > 1, "mode {mode}: thick");
                    assert_eq!((l.block_w * l.block_h * l.block_d) << e, l.block_bytes, "mode {mode} e {e}");
                    let mut seen = vec![false; l.block_bytes >> e];
                    for z in 0..l.block_d {
                        for y in 0..l.block_h {
                            for x in 0..l.block_w {
                                let o = l.offset_z(x, y, z, l.block_w);
                                assert_eq!(o & ((1 << e) - 1), 0, "mode {mode} e {e} {cfg:?}: misaligned");
                                assert!(!std::mem::replace(&mut seen[o >> e], true), "mode {mode} e {e} {cfg:?}: ({x},{y},{z}) collides");
                            }
                        }
                    }
                }
            }
        }
        // thin 3D modes are the 2D layout; 3D textures cannot use the D / 256 B modes
        let cfg = PipeConfig { pipes_log2: 0, pkrs_log2: 0 };
        assert_eq!(Layout::new_3d(24, 2, cfg).unwrap().block_d, 1);
        assert!(Layout::new_3d(10, 2, cfg).is_none() && Layout::new_3d(1, 2, cfg).is_none());
    }

    /// The three volume textures of the retail TTPF archive (4 KB tiles, thick): the space each
    /// takes there. The 256×32×8 R16 one is 128 KB as 2D slices, 256 KB as thick blocks
    /// 8×16×16 (its depth padded to a block).
    #[test]
    fn thick_sizes_match_retail_volume_textures() {
        let cfg = PipeConfig { pipes_log2: 0, pkrs_log2: 0 };
        for (e, w, h, d, bytes) in [(1u32, 256u32, 32u32, 8u32, 262144usize), (3, 32, 64, 32, 524288), (3, 32, 32, 32, 262144)] {
            let c = Chain::new_3d(Layout::new_3d(5, e, cfg).unwrap(), w, h, d, 1, 1);
            assert_eq!(c.slice_bytes * c.layers(), bytes, "{w}x{h}x{d} e{e}");
        }
        let l = Layout::new_3d(5, 1, cfg).unwrap();
        assert_eq!((l.block_w, l.block_h, l.block_d), (8, 16, 16));
    }

    /// Every level and depth slice of a mipped 3D texture gets its own elements (thick 4 KB /
    /// 64 KB with a mip tail, thin, linear).
    #[test]
    fn volume_levels_do_not_overlap() {
        let cfg = PipeConfig { pipes_log2: 0, pkrs_log2: 0 };
        for (mode, e, w, h, d, mips) in [(5u32, 2u32, 64u32, 32u32, 16u32, 7u32), (9, 0, 128, 128, 64, 8), (9, 4, 32, 32, 32, 6), (24, 2, 64, 64, 4, 5), (0, 1, 40, 8, 3, 4)] {
            let c = Chain::new_3d(Layout::new_3d(mode, e, cfg).unwrap(), w, h, d, 1, mips);
            let mut mem = vec![0u8; c.slice_bytes * c.layers()];
            let mut want = Vec::new();
            let mut n = 7u32;
            for (i, l) in c.levels.iter().enumerate() {
                let lin: Vec<u8> = (0..(l.width * l.height * l.depth) << e)
                    .map(|_| {
                        n = n.wrapping_mul(1_103_515_245).wrapping_add(12345);
                        (n >> 16) as u8 | 1
                    })
                    .collect();
                c.tile_volume(&mut mem, i, &lin);
                want.push(lin);
            }
            for (i, lin) in want.iter().enumerate() {
                assert_eq!(&c.detile_volume(&mem, i), lin, "mode {mode} e{e}: level {i} overwritten");
            }
        }
    }

    /// Linear: rows padded to 256 bytes, levels from the smallest (addrlib
    /// HwlComputeSurfaceInfoLinear); a level is padded from mip 0 halved rounding up (as the
    /// console's layout library lays it out).
    #[test]
    fn linear_rows_are_padded_to_256_bytes() {
        let l = Layout::new(0, 2, PipeConfig { pipes_log2: 0, pkrs_log2: 0 }).unwrap();
        assert_eq!((l.block_w, l.block_h, l.block_bytes), (64, 1, 256));
        assert_eq!(l.offset(3, 2, 100), (2 * 128 + 3) * 4); // 100 px → 128 px per row
        let c = Chain::new(l, 100, 30, 1, 3);
        // mip 2 (25×7, padded from 30 / 4 → 8 rows of 64 px), mip 1 (50×15), mip 0 (100×30)
        assert_eq!((c.levels[2].height, c.levels[2].offset, c.levels[1].offset, c.levels[0].offset), (7, 0, 8 * 256, 8 * 256 + 15 * 256));
        assert_eq!(c.slice_bytes, 8 * 256 + 15 * 256 + 30 * 512);
    }

    /// SW_256B_S with bytes: a 16×16 block stored row by row (addrlib's first nibble row)
    #[test]
    fn sw_256b_s_bytes_are_row_major() {
        let l = Layout::new(1, 0, PipeConfig { pipes_log2: 0, pkrs_log2: 0 }).unwrap();
        assert_eq!((l.block_w, l.block_h), (16, 16));
        assert_eq!(l.offset(5, 3, 16), 3 * 16 + 5);
        assert_eq!(l.offset(1, 16, 32), 2 * 256 + 1); // second block row of a 2-block-wide surface
    }

    #[test]
    fn t_sharp_bc7_layout() {
        let t = crate::gpu::desc::Image {
            address: 0x1_2345_0000 | 0x300,
            format: 181,
            width: 256,
            height: 130,
            depth: 1,
            ty: crate::gpu::desc::ImageType::D2,
            base_level: 0,
            last_level: 0,
            max_mip: 0,
            base_array: 0,
            dst_sel: [4, 5, 6, 7],
            swizzle_mode: 10,
            min_lod: 0.0,
        };
        let (l, w, h) = image_layout(&t, PipeConfig { pipes_log2: 0, pkrs_log2: 0 }).unwrap();
        assert_eq!((w, h, l.block_w, l.block_h, l.base_xor), (64, 33, 64, 64, 0x300));
        assert_eq!(l.size(w, h), 65536); // 33 block rows fit one 64×64 tile
        assert_eq!(element(56), Some((2, 1)));
        assert_eq!(element(72), None);
    }

    #[test]
    fn tile_then_detile_round_trips_with_partial_blocks() {
        let l = Layout::new(25, 2, PipeConfig { pipes_log2: 4, pkrs_log2: 2 }).unwrap();
        let (w, h) = (200, 130);
        let lin: Vec<u8> = (0..w * h * 4).map(|i| (i * 7 + i / 977) as u8).collect();
        let t = l.tile(&lin, w, h);
        assert_eq!(t.len(), 2 * 2 * 65536);
        assert_eq!(l.detile(&t, w, h), lin);
    }

    /// The patterns found by eye on retail console textures are addrlib's SW_64KB_D (64 KB
    /// tiles) and SW_4KB_S (4 KB tiles), bit for bit.
    #[test]
    fn standard_swizzle_matches_the_retail_texture_patterns() {
        let retail: [(u32, u32, &str); 10] = [
            (10, 4, "xyxyyxyxyxyx"),
            (5, 4, "yyxxyxyx"),
            (10, 3, "xyxxyyxyxyxyx"),
            (5, 3, "xyyxxyxyx"),
            (10, 2, "xxyyxyyxyxyxyx"),
            (5, 2, "xxyyyxyxyx"),
            (10, 1, "xxxyyyxyxyxyxyx"),
            (5, 1, "xxxyyyxyxyx"),
            (10, 0, "xxxyyyxyyxyxyxyx"),
            (5, 0, "xxxxyyyyyxyx"),
        ];
        for (mode, e, want) in retail {
            let l = Layout::new(mode, e, PipeConfig { pipes_log2: 0, pkrs_log2: 0 }).unwrap();
            // bit i of the element index: which coordinate moves it
            let got: String = (0..want.len())
                .map(|i| {
                    let bit = 1u32 << (i as u32 + e);
                    if l.ox.iter().any(|&o| o == bit) {
                        'x'
                    } else if l.oy.iter().any(|&o| o == bit) {
                        'y'
                    } else {
                        '?'
                    }
                })
                .collect();
            assert_eq!(got, want, "mode {mode}, {} B elements", 1 << e);
        }
    }
}

